/**
 * scripts/audit_project.ts
 * 
 * STABLE PROJECT AUDIT ENGINE (Node.js 26+)
 * 
 * Final Safe Version: Context-aware GPU checking.
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';
import { parseArgs } from 'node:util';

enableCompileCache();

const IGNORE_DIRS = new Set(['node_modules', '.git', 'dist', 'backup_legacy_code', 'public', 'docs', 'scratch']);
const AUDIT_EXTENSIONS = new Set(['.vue', '.scss', '.css', '.ts', '.js']);


interface AuditRule {
  regex: RegExp;
  message: string | ((match: string) => string);
  fix?: (match: string) => string;
  check?: (context: string, match: RegExpExecArray) => boolean;
  severity?: 'error' | 'warning';
  fixable?: boolean;
  addImport?: string;
  maxLines?: number;
  ignorePattern?: RegExp;
}

interface Violation {
  file: string; line: number; message: string; context: string; severity: 'error' | 'warning'; fixable: boolean;
}

const viewport: AuditRule = {
  regex: /\b\d+(?:\.\d+)?(vw|vh)\b/gi,
  message: (match: string) => `Unidad legacy detectada: '${match}'. Usa 'd${match.slice(-2)}' para soporte mobile dinámico.`,
  fix: (match: string) => `d${match.toLowerCase().slice(-2)}`
};


const gpuGaps: AuditRule = {
  regex: /(backdrop-filter|filter):/gi,
  message: "Filtro detectado sin 'will-change'. Considera añadir promoción de capa.",
  check: (content: string, match: RegExpExecArray) => {
    const start = Math.max(0, match.index - 500);
    const end = Math.min(content.length, match.index + 500);
    const context = content.substring(start, end);
    return !/will-change/gi.test(context);
  },
  fixable: false 
};

const legacyDates: AuditRule = {
  regex: /new Date\(|Date\.now\(\)/g,
  message: "Uso de 'Date' detectado. Usa 'Temporal'.",
  fixable: false
};

const nodePrefix: AuditRule = {
  regex: /import .* from ['"](fs|path|os|crypto|util|url|events|stream|child_process)['"]/g,
  message: "Import de Node sin prefijo 'node:'.",
  fix: (match: string) => match.replace(/['"](fs|path|os|crypto|util|url|events|stream|child_process)['"]/, (m) => m.slice(0, 1) + 'node:' + m.slice(1))
};

const esmExtensions: AuditRule = {
  // Match relative imports WITHOUT an extension (not .ts, .js, or .vue at the end)
  regex: /import .* from ['"](\.\.[^'"]*(?<!\.[jt]s)(?<!\.vue))['"]|import .* from ['"](\.[^/][^'"]*(?<!\.[jt]s)(?<!\.vue))['"]/g,
  message: (match: string) => `Import relativo sin extensión: '${match}'. En Node.js 26+ nativo las extensiones son obligatorias.`,
  // Fix: only add .ts when the path doesn't already end with .vue, .js, or .ts
  fix: (match: string) => match.replace(/(['"])(\.\.?\/[^'"]+)(?<!\.[jt]s)(?<!\.vue)(['"])/g, '$1$2.ts$3'),
  // Only applies to pure .ts files in src/logic, scripts — NOT .vue files (handled by Vite resolver)
  check: (filePath: string) => !filePath.endsWith('.vue')
};

const tsIgnore: AuditRule = {
  regex: /\/\/\s*@ts-(ignore|nocheck|expect-error)/g,
  message: "Uso de supresión de TypeScript detectado. Prohibido por la política 'Zero-Ignore'.",
  severity: 'error',
  fix: () => '',
  fixable: true
};

const timersPromises: AuditRule = {
  regex: /new Promise\(r => setTimeout\(r, (\d+)\)\)/g,
  message: "Uso de setTimeout manual en script Node. Considera 'import { setTimeout } from \"node:timers/promises\"'.",
  // Only report in scripts/ — NEVER auto-fix via addImport (caused mass injection)
  check: (filePath: string) => filePath.includes('scripts' + path.sep) && !filePath.includes('node_modules'),
  fixable: false
  // NOTE: addImport removed intentionally — it caused spurious injection in src/ frontend files.
};

const explicitResource: AuditRule = {
  regex: /const (\w+) = (new DatabaseSync|fs\.openSync)/g,
  message: "Recurso detectado sin 'using'. Usa Explicit Resource Management (Node 26+).",
  fix: (match: string) => match.replace('const', 'using'),
  check: (filePath: string) => filePath.includes('scripts' + path.sep)
};

const fileLength: AuditRule = {
  regex: /[\s\S]*/,
  message: "Archivo demasiado largo.",
  maxLines: 500,
  ignorePattern: /\[PureVue-Ignore-Length\]/
};

const SASS_TRAPS = [
  'scale', 'grayscale', 'invert', 'opacity', 'brightness', 
  'blur', 'rotate', 'translate', 'saturate', 'drop-shadow',
  'translatex', 'translatey', 'translatez', 'skewx', 'skewy', 'matrix',
  'rgba', 'rgb'
];

const sassTraps: AuditRule = {
  regex: /([.$])?\b([a-zA-Z0-9-]+)\(/g,
  message: (match: string) => `Función SASS/CSS detectada sin capitalización: '${match}'. El plugin de Vite la capitalizará, pero se recomienda escribirla correctamente.`,
  fixable: false
};

const config = {
  viewport, gpuGaps, legacyDates, nodePrefix, esmExtensions, tsIgnore, timersPromises, explicitResource, fileLength, sassTraps
};

async function getFilesToAudit(dir: string): Promise<string[]> {
  const files: string[] = [];
  const pattern = `**/*{${Array.from(AUDIT_EXTENSIONS).join(',')}}`;

  for await (const entry of fs.glob(pattern, { cwd: dir, exclude: (p: string) => Array.from(IGNORE_DIRS).some(d => p.includes(d)) })) {
    files.push(path.resolve(dir, entry));
  }
  return files;
}

async function auditFile(filePath: string, fix: boolean): Promise<Violation[]> {
  const violations: Violation[] = [];
  let content = await fs.readFile(filePath, 'utf-8');
  let modified = false;

  const isVue = filePath.endsWith('.vue');
  const isLogic = filePath.endsWith('.ts') || filePath.endsWith('.js');
  const isStyle = filePath.endsWith('.scss') || filePath.endsWith('.css');

  if (isLogic || isVue) {
    const tag = 'script';
    const block = isVue ? extractBlock(content, tag) : content;
    if (block) {
      const allRules: AuditRule[] = [legacyDates, nodePrefix, esmExtensions, tsIgnore, timersPromises, explicitResource];
      let rules: AuditRule[] = allRules;

      // EXCEPCIÓN: Ignorar 'legacyDates' en scripts de utilidad/migración
      if (filePath.includes('scripts' + path.sep) || filePath.includes('audit_project.ts')) {
        rules = rules.filter(r => r !== config.legacyDates);
      }

      let newBlock = runRules(filePath, block, rules, violations, fix, isVue ? findBlockStart(content, tag) : 0);

      // Post-fix: Añadir imports necesarios si se aplicaron correcciones
      if (fix && newBlock !== block) {
        for (const rule of rules) {
          const importer = rule.addImport;
          if (importer && newBlock.includes(importer.split(' ')[1]!) && !newBlock.includes(importer)) {
            newBlock = importer + '\n' + newBlock;
          }
        }
        content = isVue ? injectBlock(content, tag, newBlock) : newBlock;
        modified = true;
      }
    }
  }

  if (isStyle || isVue) {
    const tag = 'style';
    const block = isVue ? extractBlock(content, tag) : content;
    if (block) {
      const newBlock = runRules(filePath, block, [config.viewport, config.gpuGaps], violations, fix, isVue ? findBlockStart(content, tag) : 0);
      if (fix && newBlock !== block) {
        content = isVue ? injectBlock(content, tag, newBlock) : newBlock;
        modified = true;
      }
    }
  }

  if (fix && modified) {
    await fs.writeFile(filePath, content, 'utf-8');
  }

  return violations;
}

function runRules(filePath: string, content: string, rules: AuditRule[], violations: Violation[], fix: boolean, offset: number): string {
  let result = content;
  for (const rule of rules) {
    const regex = new RegExp(rule.regex.source, rule.regex.flags);
    let match;
    while ((match = regex.exec(content)) !== null) {
      // 1. Specialized checks
      if (rule === config.sassTraps) {
        if (match[1]) continue; 
        if (!SASS_TRAPS.includes(match[2].toLowerCase())) continue; 
        if (match[2].charAt(0) === match[2].charAt(0).toUpperCase()) continue; 
      }

      if (rule.check) {
        if (rule === config.gpuGaps) {
          if (!rule.check(content, match)) continue;
        } else {
          if (!rule.check(filePath, match)) continue;
        }
      }

      const lineNo = content.substring(0, match.index).split('\n').length + offset;
      violations.push({
        file: filePath, line: lineNo, message: typeof rule.message === 'function' ? rule.message(match[0]) : rule.message, 
        context: match[0], severity: rule.severity || 'warning', fixable: !!rule.fix
      });
    }
    const fixer = rule.fix;
    if (fix && fixer) {
      const gRegex = new RegExp(rule.regex.source, rule.regex.flags.includes('g') ? rule.regex.flags : rule.regex.flags + 'g');

      // Aplicar fix solo si pasa el check (contexto-aware)
      result = result.replace(gRegex, (match, ...args) => {
        // Necesitamos recrear el match array para el check
        const execMatch = rule.regex.exec(content);
        if (rule.check) {
          const pass = (rule === config.gpuGaps) 
            ? rule.check(content, execMatch!) 
            : rule.check(filePath, execMatch!);
          if (!pass) return match;
        }
        return fixer(match);
      });
    }
  }
  return result;
}

function extractBlock(content: string, tag: string): string | null {
  const match = content.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)<\\/${tag}>`, 'i'));
  return match ? match[1] : null;
}

function findBlockStart(content: string, tag: string): number {
  const match = content.match(new RegExp(`<${tag}[^>]*>`, 'i'));
  return match ? content.substring(0, match.index!).split('\n').length : 0;
}

function injectBlock(content: string, tag: string, block: string): string {
  return content.replace(new RegExp(`(<${tag}[^>]*>)[\\s\\S]*?(<\\/${tag}>)`, 'i'), `$1${block}$2`);
}

async function main() {
  const { values } = parseArgs({ options: { fix: { type: 'boolean', short: 'f' }, path: { type: 'string', short: 'p', default: '.' } } });
  console.log(styleText('bold', '\n--- 🔎 POKE VICIO - INTELLIGENT AUDIT ---'));
  const files = await getFilesToAudit(path.resolve(process.cwd(), values.path as string));
  let all: Violation[] = [];
  for (const f of files) all = all.concat(await auditFile(f, !!values.fix));
  all.forEach(v => console.log(styleText(v.severity === 'error' ? 'red' : 'yellow', `[${v.severity.toUpperCase()}] ${path.relative(process.cwd(), v.file)}:${v.line} -> ${v.message} ("${v.context}")`)));
  console.log(`\n❌ Errores: ${all.filter(v=>v.severity==='error').length} | ⚠️ Advertencias: ${all.filter(v=>v.severity==='warning').length}`);
  if (values.fix) console.log(styleText('cyan', '✨ Correcciones aplicadas.'));
}
main();

/**
 * scripts/validate_items.ts
 * 
 * ITEM VALIDATOR SCRIPT (Node.js 26+)
 * Validates integrity of SHOP_ITEMS and HEALING_ITEMS across:
 *   - src/data/items.js            -> SHOP_ITEMS[]
 *   - src/logic/items/itemEffects.js -> HEALING_ITEMS{}
 *
 * Usage: npm run validate:items
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';

enableCompileCache();

// Runtime permission check
if (process.permission && !process.permission.has('fs.read', process.cwd())) {
  console.error(styleText('red', '\n❌ Error: Este script requiere permisos de lectura. Ejecútalo con --permission --allow-fs-read=.\n'));
  process.exit(1);
}

const SHOP_FILE   = path.resolve(process.cwd(), 'src/data/items.ts');
const BATTLE_FILE = path.resolve(process.cwd(), 'src/logic/items/itemEffects.ts');

interface ShopItem {
  id: string;
  _line: number;
  name?: string | null;
  cat?: string | null;
  sprite?: string | null;
  icon?: string | null;
  desc?: string | null;
  type?: string | null;
  price?: number | null;
  market?: boolean | null;
  [key: string]: unknown;
}

async function main() {
  console.log(styleText('bold', '\n--- 🛡️  ITEM INTEGRITY VALIDATOR ---'));

  try {
    await fs.access(SHOP_FILE);
    await fs.access(BATTLE_FILE);
  } catch {
    console.error(styleText('red', `❌ Required files not found.\n   - ${SHOP_FILE}\n   - ${BATTLE_FILE}`));
    process.exit(1);
  }

  const shopContent   = await fs.readFile(SHOP_FILE, 'utf8');
  const battleContent = await fs.readFile(BATTLE_FILE, 'utf8');

  // ─── 1. Extract SHOP_ITEMS entries (line-based parser) ───────────────────────
  const shopLines = shopContent.split('\n');
  const shopItems: ShopItem[] = [];
  const shopStart = shopLines.findIndex(l => l.includes('SHOP_ITEMS') && l.includes('['));
  const shopEnd   = shopLines.length;

  let current: ShopItem | null = null;

  for (let i = shopStart; i < shopEnd; i++) {
    const line = shopLines[i]!;
    const idMatch = line.match(/\bid:\s*'([^']+)'/);
    if (idMatch) {
      if (current && current.name && current.cat) shopItems.push(current);
      current = { id: idMatch[1]!, _line: i + 1 };
    }

    if (!current) continue;

    const tryMatch = (rx: RegExp) => { const m = line.match(rx); return m ? m[1] : null; };

    if (!current.name)   current.name   = tryMatch(/\bname:\s*'([^']+)'/);
    if (!current.cat)    current.cat    = tryMatch(/\bcat:\s*'([^']+)'/);
    if (!current.sprite) current.sprite = tryMatch(/\bsprite:\s*'([^']+)'/);
    if (!current.icon)   current.icon   = tryMatch(/\bicon:\s*'([^']+)'/);
    if (!current.desc)   current.desc   = tryMatch(/\bdesc:\s*'([^']+)'/);
    if (!current.type)   current.type   = tryMatch(/\btype:\s*'([^']+)'/);

    const priceM  = line.match(/\bprice:\s*(\d+)/);
    const marketM = line.match(/\bmarket:\s*(true|false)/);
    if (priceM  && current.price  == null) current.price  = parseInt(priceM[1]!);
    if (marketM && current.market == null) current.market = marketM[1] === 'true';
  }
  if (current && current.name && current.cat) shopItems.push(current);

  // ─── 2. Extract HEALING_ITEMS keys ───────────────────────────────────────────
  const healingItems = new Set<string>();
  const healingRegex = /^\s+'([^']+)':\s*\(?[\s\S]*?\)?\s*=>/gm;
  let m;
  while ((m = healingRegex.exec(battleContent)) !== null) {
    healingItems.add(m[1]);
  }

  // ─── Run validations ──────────────────────────────────────────────────────────
  const errors: string[]   = [];
  const warnings: string[] = [];

  const MUST_BE_USABLE     = ['pociones', 'utility', 'booster', 'stones'];
  const MUST_NOT_BE_USABLE = ['held', 'pokeballs', 'breeding'];
  const REQUIRED_FIELDS    = ['id', 'name', 'cat', 'sprite', 'icon', 'desc', 'price'];
  const VALID_CATS         = [
    'pociones', 'utility', 'booster', 'especial', 'held', 'pokeballs', 'stones', 'breeding',
    'healing', 'tm', 'special', 'stone'
  ];
  const SELL_ONLY_ESPECIAL = new Set([
    'Pepita', 'Perla', 'Perla Grande', 'Polvo Estelar', 'Trozo Estrella', 'Escama Dragón'
  ]);

  shopItems.forEach(item => {
    const tag = `[${item.name || item.id} (line ~${item._line})]`;

    REQUIRED_FIELDS.forEach(f => {
      const val = item[f];
      if (val == null || val === '') {
        errors.push(`${tag} Missing required field: '${f}'`);
      }
    });

    if (item.cat && !VALID_CATS.includes(item.cat)) {
      errors.push(`${tag} Unknown category: '${item.cat}'`);
    }

    if (item.cat && MUST_BE_USABLE.includes(item.cat) && item.name && !healingItems.has(item.name)) {
      if (!item.name.startsWith('MT')) {
        errors.push(`${tag} cat='${item.cat}' but '${item.name}' has no entry in HEALING_ITEMS.`);
      }
    }

    if (item.cat && MUST_NOT_BE_USABLE.includes(item.cat) && item.name && healingItems.has(item.name)) {
      errors.push(`${tag} cat='${item.cat}' should NOT be in HEALING_ITEMS.`);
    }

    if (item.cat === 'held' && item.type !== 'held') {
      errors.push(`${tag} cat='held' but missing 'type: held'.`);
    }

    // TMs are handled dynamically in getDynamicItemEffect, so they don't need to be in the main object
    if (item.name?.startsWith('MT')) return;
  });

  const shopItemNames = new Set(shopItems.map(i => i.name));

  healingItems.forEach(name => {
    if (name.startsWith('MT')) return;
    if (!shopItemNames.has(name)) {
      warnings.push(`[PHANTOM] '${name}' is in HEALING_ITEMS but has NO entry in SHOP_ITEMS.`);
    }
  });

  console.log(`\n════════════════════════════════════`);
  console.log(`    ITEM INTEGRITY REPORT`);
  console.log(`════════════════════════════════════`);
  console.log(`📦 SHOP_ITEMS scanned:    ${shopItems.length}`);
  console.log(`💊 HEALING_ITEMS scanned: ${healingItems.size}`);
  console.log(`════════════════════════════════════\n`);

  if (warnings.length) {
    console.log(styleText('yellow', `⚠️  WARNINGS (${warnings.length}):`));
    warnings.forEach(w => console.log(`   ${w}`));
    console.log('');
  }

  if (errors.length) {
    console.log(styleText('red', `❌ ERRORS (${errors.length}):`));
    errors.forEach(e => console.log(`   ${e}`));
    console.log('\n' + styleText('red', 'Fix these errors before considering items complete.'));
    process.exit(1);
  } else {
    console.log(styleText('green', '✅ All items passed validation! SHOP_ITEMS and HEALING_ITEMS are in sync.'));
  }
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Fatal error: ${err.message}`));
  process.exit(1);
});

/**
 * scripts/validate_moves.ts
 * 
 * MOVE INTEGRITY VALIDATOR (Node.js 26+)
 * Validates integrity of MOVE_DATA against learnsets, semantic rules, and PokeAPI.
 * 
 * Usage: npm run validate:moves
 */

import fs from 'node:fs/promises';
import path from 'node:path';
import { styleText } from 'node:util';
import { enableCompileCache } from 'node:module';

enableCompileCache();

interface PokeApiMoveListResponse {
  results: Array<{ name: string; url: string }>;
}

interface PokeApiMove {
  name: string;
  names: Array<{ name: string; language: { name: string } }>;
  meta?: {
    category?: { name: string };
  };
  effect_chance?: number;
  effect_entries: Array<{
    short_effect: string;
    language: { name: string };
  }>;
}

const DB_FILE = path.resolve(process.cwd(), 'src/data/pokemonDB.ts');
const MOVES_FILE = path.resolve(process.cwd(), 'src/data/moves.ts');
const UTILS_FILE = path.resolve(process.cwd(), 'src/logic/pokemonUtils.ts');
const CACHE_DIR = path.resolve(process.cwd(), 'scripts/.cache');
const CACHE_FILE = path.join(CACHE_DIR, 'pokeapi_move_cache.json');

function normalizeName(name: string) {
  return name.toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]/g, '');
}

async function getPokeApiMoves(): Promise<PokeApiMove[]> {
  try {
    await fs.mkdir(CACHE_DIR, { recursive: true });
    const cacheExists = await fs.access(CACHE_FILE).then(() => true).catch(() => false);

    if (cacheExists) {
      console.log(styleText('blue', "ℹ️ Cargando movimientos de PokeAPI desde la caché..."));
      return JSON.parse(await fs.readFile(CACHE_FILE, 'utf8')) as PokeApiMove[];
    }
  } catch {
    console.log(styleText('yellow', "⚠️ No se pudo acceder a la caché de PokeAPI."));
  }

  console.log(styleText('cyan', "🌐 Obteniendo movimientos de PokeAPI (esto puede tardar unos segundos)..."));

  try {
    const response = await fetch('https://pokeapi.co/api/v2/move?limit=354');
    if (!response.ok) throw new Error(`Status: ${response.status}`);
    const listResp = await response.json() as PokeApiMoveListResponse;

    const results: PokeApiMove[] = [];
    const chunkSize = 20;

    for (let i = 0; i < listResp.results.length; i += chunkSize) {
      const chunk = listResp.results.slice(i, i + chunkSize);
      const promises = chunk.map(async (entry: { url: string }) => {
        const res = await fetch(entry.url);
        if (!res.ok) return null;
        return res.json() as Promise<PokeApiMove>;
      });

      const chunkResults = await Promise.all(promises);
      results.push(...chunkResults.filter((item): item is PokeApiMove => !!item));
      process.stdout.write(`Obtenidos ${Math.min(i + chunkSize, listResp.results.length)} / ${listResp.results.length}\r`);
    }

    console.log(styleText('green', "\n✅ Descarga de movimientos completada."));
    await fs.writeFile(CACHE_FILE, JSON.stringify(results, null, 2));
    return results;
  } catch (error: unknown) {
    console.error(styleText('red', `\n❌ Error al conectar con PokeAPI: ${(error as Error).message}`));
    return [];
  }
}

async function main() {
  console.log(styleText('bold', '\n--- 🛡️  POKEMON MOVE VALIDATOR ---'));

  try {
    await fs.access(DB_FILE);
    await fs.access(MOVES_FILE);
  } catch (e) {
    console.error(styleText('red', `❌ Archivos de datos no encontrados.`));
    process.exit(1);
  }

  const dbContent = await fs.readFile(DB_FILE, 'utf8');
  const movesContent = await fs.readFile(MOVES_FILE, 'utf8');

  const errors: string[] = [];
  const warnings: string[] = [];

  // 1. Extract moves from learnsets
  const learnsetBlockRegex = /learnset:\s*\[([\s\S]+?)\]/g;
  const moveNameRegex = /name:\s*'([^']+)'/g;
  const learnsetMoves = new Set<string>();

  let blockMatch;
  while ((blockMatch = learnsetBlockRegex.exec(dbContent)) !== null) {
    const block = blockMatch[1]!;
    let nameMatch;
    while ((nameMatch = moveNameRegex.exec(block)) !== null) {
      if (nameMatch[1] !== 'Unknown') learnsetMoves.add(nameMatch[1]!);
    }
  }

  // 2. Extract defined moves from MOVE_DATA
  const definedMoves = new Map<string, { line: number, content: string }>();
  const movesLines = movesContent.split('\n');

  movesLines.forEach((line, index) => {
    const match = line.match(/'([^']+)':\s*\{/);
    if (match) {
      const name = match[1]!;
      if (definedMoves.has(name)) {
        errors.push(`[${name}] Duplicado en MOVE_DATA (Línea ${index + 1}).`);
      }
      definedMoves.set(name, { line: index + 1, content: line });
    }
  });

  console.log(`📊 Movimientos en learnsets: ${learnsetMoves.size}`);
  console.log(`📚 Movimientos definidos en MOVE_DATA: ${definedMoves.size}\n`);

  const apiMoves = await getPokeApiMoves();

  // 3. Structural & Semantic Validation
  learnsetMoves.forEach(move => {
    if (!definedMoves.has(move)) {
      errors.push(`[${move}] Aparece en un learnset pero NO está definido en MOVE_DATA.`);
    }
  });

  definedMoves.forEach((data, name) => {
    const { content, line } = data;
    const tag = `[${name} (Línea ${line})]`;

    // Status moves with power > 0
    if (content.includes("cat: 'status'") && content.match(/power:\s*([1-9]\d*)/)) {
      errors.push(`${tag} Movimiento de estado con potencia mayor a 0.`);
    }

    // Specific move checks
    if (name === 'Furia Dragón' && !content.includes('fixedDmg: 40')) {
      errors.push(`${tag} Falta 'fixedDmg: 40'.`);
    }
    if (name === 'Súper Colmillo' && !content.includes('halfHP: true')) {
      errors.push(`${tag} Falta 'halfHP: true'.`);
    }
    if (name === 'Esfuerzo' && !content.includes('endeavor: true')) {
      errors.push(`${tag} Falta 'endeavor: true'.`);
    }

    // Schema enforcement
    const boolProps = ['halfHP', 'ohko', 'selfKO', 'endeavor'];
    boolProps.forEach(prop => {
      if (content.includes(`effect: '${prop}'`)) {
        errors.push(`${tag} Usa "effect: '${prop}'" en lugar del esquema requerido "${prop}: true".`);
      }
    });

    if (content.includes("effect: 'fixedDmg'")) {
      errors.push(`${tag} Usa "effect: 'fixedDmg'" en lugar de "fixedDmg: X".`);
    }

    // PokeAPI Semantic Sync
    if (apiMoves.length > 0) {
      const norm = normalizeName(name);
      const apiMove = apiMoves.find((m: PokeApiMove) => m.names.some((n: { name: string; language: { name: string } }) => n.language.name === 'es' && normalizeName(n.name) === norm));

      if (apiMove) {
        const apiCat = apiMove.meta?.category?.name || '';
        const apiChance = apiMove.effect_chance;
        const apiEffectEntries = apiMove.effect_entries.find((e: { language: { name: string } }) => e.language.name === 'en')?.short_effect || '';

        // Check for missing effects based on category
        if (apiCat && apiCat !== 'damage' && !content.includes('effect:') && !content.match(/(ohko|drain|recoil|endeavor|halfHP|fixedDmg):/)) {
          if (!content.includes("cat: 'status'")) {
            warnings.push(`${tag} Podría faltar lógica de efecto (Categoría PokeAPI: '${apiCat}').`);
          }
        }

        // Check for effect chance mismatch
        if (apiChance && content.includes('effect:')) {
          const ourChanceMatch = content.match(/_(\d+)'/);
          const ourChance = ourChanceMatch ? parseInt(ourChanceMatch[1]!) : 100;
          if (ourChance !== apiChance) {
            warnings.push(`${tag} Discrepancia en probabilidad de efecto: PokeAPI ${apiChance}% vs Local ${ourChance}%.`);
          }
        }

        // Check for flinch
        if (apiEffectEntries.toLowerCase().includes('flinch') && !content.includes('flinch')) {
          warnings.push(`${tag} PokeAPI menciona 'flinch', pero no se detectó en la definición local.`);
        }
      }
    }
  });

  // 4. UI Description Parity
  try {
    const utilsContent = await fs.readFile(UTILS_FILE, 'utf8');
    const effectsMatch = utilsContent.match(/const effects:.* = {([\s\S]+?)};/);
    if (effectsMatch) {
      const registeredEffects = new Set<string>();
      const keyRegex = /'([^']+)':/g;
      let k;
      while ((k = keyRegex.exec(effectsMatch[1]!)) !== null) {
        registeredEffects.add(k[1]!);
      }

      definedMoves.forEach((data, name) => {
        const eMatch = data.content.match(/effect:\s*'([^']+)'/);
        if (eMatch) {
          const effectName = eMatch[1]!;
          if (!registeredEffects.has(effectName)) {
            warnings.push(`[${name}] Usa el efecto '${effectName}' pero no tiene descripción en pokemonUtils.ts.`);
          }
        }
      });
    }
  } catch (e) {
    warnings.push(`No se pudo validar pokemonUtils.ts para descripciones de efectos.`);
  }

  console.log(`\n════════════════════════════════════`);
  console.log(`    REPORTE DE INTEGRIDAD DE MOVIMIENTOS`);
  console.log(`════════════════════════════════════\n`);

  if (warnings.length) {
    console.log(styleText('yellow', `⚠️  ADVERTENCIAS (${warnings.length}):`));
    warnings.forEach(w => console.log(`   ${w}`));
    console.log('');
  }

  if (errors.length) {
    console.log(styleText('red', `❌ ERRORES (${errors.length}):`));
    errors.forEach(e => console.log(`   ${e}`));
    console.log('\n' + styleText('red', 'Corrige estos errores en src/data/moves.ts.'));
    process.exit(1);
  } else {
    console.log(styleText('green', '✅ Todos los movimientos pasaron la validación de integridad.'));
  }
}

main().catch(err => {
  console.error(styleText('red', `\n💥 Error fatal: ${err.message}`));
  process.exit(1);
});

